const {getDatabase}=require('../_db');const {authenticatedUser}=require('./_auth');
module.exports=async function handler(req,res){if(req.method!=='GET')return res.status(405).json({error:'Método não permitido'});if(!await authenticatedUser(req))return res.status(401).json({error:'Sessão expirada.'});try{const sql=getDatabase();const rows=await sql`SELECT id,nome_exibicao,nome_completo,login,perfil FROM usuarios_atendimento WHERE ativo=TRUE ORDER BY nome_exibicao ASC`;return res.status(200).json({atendentes:rows})}catch(error){console.error(error);return res.status(500).json({error:'Não foi possível carregar os atendentes.'})}};
